for (const track of tracks) {
  const interview = (await content(track.interview)).toLowerCase();
  for (const [topic, interviewTerm, canonicalId, canonicalTerms] of track.topics) {
    if (!interview.includes(interviewTerm.toLowerCase())) {
      failures.push(`${track.interview}: missing ${track.name} interview topic ${topic}`);
    }
    const canonical = (await content(canonicalId)).toLowerCase();
    for (const term of canonicalTerms) {
      if (!canonical.includes(term.toLowerCase())) {
        failures.push(`${canonicalId}: ${topic} is missing canonical term ${term}`);
      }
    }
  }
}

const topicCount = tracks.reduce((total, track) => total + track.topics.length, 0);
console.log(`Cross-track interview coverage audit: ${topicCount} topics across ${tracks.length} tracks checked.`);
if (failures.length) {
  failures.forEach((failure) => console.error(`- ${failure}`));
  process.exitCode = 1;
} else {
  console.log('Spring Boot, Spring Cloud, microservices, distributed-systems, Kafka, database-engineering, security, Docker, Kubernetes, cloud/AWS, observability, SRE/incident response, CI/CD, performance, testing, Java, REST, gRPC, networking, Linux, build engineering, system design, LLD, DDD, design patterns, architecture governance, engineering leadership, Redis, RabbitMQ, Elasticsearch, Cassandra, CDC/stream processing, data pipelines, algorithms, graphs, dynamic programming, backtracking/tries, concurrent coding, and machine-coding/OOD interview-to-canonical mappings are present.');
}
